#include <stdio.h>
#include <stdlib.h>
#include <sgx_urts.h>

#include "app.h"
#include "sgx_utils.h"
#include "enclave_u.h"  /* Generated by sgx_edger8r from enclave.edl. */

int main( void ) {

    sgx_enclave_id_t enclave_id = 0;
    sgx_status_t sgx_status;
    int ecall_return = -1;
    int exit_status = EXIT_FAILURE;

    /* Create an enclave instance. The SDK returns its identifier. */
    sgx_status = sgx_create_enclave( ENCLAVE_FILENAME, SGX_DEBUG_FLAG, NULL, NULL, &enclave_id, NULL);
    if ( sgx_status != SGX_SUCCESS ) {
        fprintf( stderr, "Enclave creation failed.\n" );
        print_sgx_error( sgx_status );
        return EXIT_FAILURE;
    }

    /*
     * ECALL results are separate:
     *   sgx_status   - whether the SDK could invoke the enclave function;
     *   ecall_return - the int returned by the function inside the enclave.
     */
    sgx_status = ecall_hello_message( enclave_id, &ecall_return );
    if ( sgx_status != SGX_SUCCESS ) {
        fprintf( stderr, "Enclave call failed.\n" );
        print_sgx_error( sgx_status );
    } else if ( ecall_return != 0 ) {
        fprintf( stderr, "The enclave function reported an error (%d).\n", ecall_return );
    } else {
        exit_status = EXIT_SUCCESS;
    }

    /* Release enclave resources even when the ECALL failed. */
    sgx_status = sgx_destroy_enclave( enclave_id );
    if ( sgx_status != SGX_SUCCESS ) {
        fprintf( stderr, "Enclave destruction failed.\n" );
        print_sgx_error( sgx_status );
        exit_status = EXIT_FAILURE;
    }

    return exit_status;
}

/*
 * OCALL implementation: code in the enclave requests an output operation,
 * but this function runs in the untrusted application (outside the enclave).
 */
void ocall_print_string( const char *str )
{
    /* Do not treat enclave-provided text as a printf format string. */
    fputs( str, stdout );
}

